'use strict';
// Original interaction choreography: sleeping sky → letters → emotion stars → context.
const canvas=$('sky'),ctx=canvas.getContext('2d');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let paused=reduced.matches,w=innerWidth,h=innerHeight,raf=0,previous=0,stars=[],dust=[],letters=[],shooters=[],gatherStart=0,revealTimer=0,finishTimer=0;
let pointer={x:-1000,y:-1000},scene='sleeping',currentTint='#9ba7b6',flare=0,nextMeteor=performance.now()+17000;
const sprites=new Map();
function sprite(color){if(sprites.has(color))return sprites.get(color);const c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d'),r=g.createRadialGradient(32,32,0,32,32,32);r.addColorStop(0,'#fff9e9');r.addColorStop(.045,'#fff9e9');r.addColorStop(.12,color+'dd');r.addColorStop(.3,color+'35');r.addColorStop(1,color+'00');g.fillStyle=r;g.fillRect(0,0,64,64);sprites.set(color,c);return c;}
function setScene(s){scene=s;document.body.dataset.scene=s;}
function size(){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);let seed=44017;const rand=()=>{seed=seed*16807%2147483647;return seed/2147483647;};stars=Array.from({length:Math.min(1700,Math.max(320,Math.floor(w*h/900)))},()=>{const magnitude=Math.pow(rand(),3.7);return {x:rand()*w,y:rand()*h,z:magnitude,r:.18+magnitude*.85,phase:rand()*7,glow:0,color:rand()>.82?'#dfd6c7':rand()>.65?'#c2cdda':'#d8dbe0'};});if(scene==='gathering')makeLetters();paint(performance.now(),0);}
function makeLetters(){const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');const font=getComputedStyle(document.querySelector('.feeling-line label'));g.font=`400 ${font.fontSize} ${font.fontFamily}`;g.textAlign='center';g.textBaseline='middle';g.fillStyle='white';g.fillText('Today I’m feeling …',w*.5,h*.5-12);const pixels=g.getImageData(0,0,w,h).data,points=[];for(let y=Math.max(0,Math.floor(h*.5-65));y<Math.min(h,h*.5+65);y+=3){for(let x=0;x<w;x+=3){if(pixels[(y*w+x)*4+3]>70)points.push({x,y});}}letters=points.filter((_,i)=>i%Math.max(1,Math.ceil(points.length/1400))===0).map(p=>{const a=Math.random()*Math.PI*2,r=Math.max(w,h)*(.25+Math.random()*.45);return {tx:p.x,ty:p.y,x:w*.5+Math.cos(a)*r,y:h*.5+Math.sin(a)*r,sx:w*.5+Math.cos(a)*r,sy:h*.5+Math.sin(a)*r,delay:Math.random()*.16,r:.5+Math.random()*.65};});}
function reveal(){clearTimeout(revealTimer);$('main').inert=false;$('wakeSky').hidden=true;setScene('prompt');}
function wake(instant=false){if(scene!=='sleeping')return;if(instant||paused){reveal();paint(performance.now(),0);return;}setScene('gathering');gatherStart=performance.now();makeLetters();revealTimer=setTimeout(reveal,2350);finishTimer=setTimeout(()=>letters=[],3250);}
function burst(x,y,color){if(paused)return;currentTint=color;flare=.3;for(let i=0;i<22;i++){const angle=-.32+(Math.random()-.5)*.45,speed=.35+Math.random()*.7;const px=x+(Math.random()-.5)*75,py=y+(Math.random()-.5)*10;dust.push({x:px,y:py,px,py,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,color,life:.6,decay:.006+Math.random()*.004});}if(dust.length>140)dust.splice(0,dust.length-140);}
function move(e){const old=pointer;pointer={x:e.clientX,y:e.clientY};wake();if(paused||document.querySelector('dialog[open]')||!selected)return;const dx=pointer.x-old.x,dy=pointer.y-old.y;if(Math.hypot(dx,dy)>3&&Math.hypot(dx,dy)<500){dust.push({x:pointer.x,y:pointer.y,px:old.x,py:old.y,vx:-dx*.006,vy:-dy*.006-.08,color:selected.color,life:.4,decay:.013});}if(dust.length>140)dust.splice(0,dust.length-140);}
function paint(now,dt){ctx.clearRect(0,0,w,h);ctx.globalCompositeOperation='source-over';const atmosphere=ctx.createRadialGradient(w*.46,h*.61,0,w*.46,h*.61,w*.7);atmosphere.addColorStop(0,'#3440520d');atmosphere.addColorStop(.55,'#20283506');atmosphere.addColorStop(1,'#00000000');ctx.fillStyle=atmosphere;ctx.fillRect(0,0,w,h);
 ctx.globalCompositeOperation='lighter';
 for(const s of stars){const x=s.x,y=s.y,distance=Math.hypot(x-pointer.x,y-pointer.y);s.glow+=(Math.max(0,1-distance/105)-s.glow)*Math.min(1,dt*.005);const tw=paused?1:1+.065*Math.sin(now*.00055+s.phase)+.025*Math.sin(now*.00131+s.phase*2);ctx.globalAlpha=Math.min(.95,(.09+s.z*.66)*tw+s.glow*.17);ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(x,y,s.r,0,Math.PI*2);ctx.fill();if(s.z>.82){ctx.globalAlpha=(s.z-.82)*.9+s.glow*.04;const radius=3+s.z*2;ctx.drawImage(sprite(s.color),x-radius,y-radius,radius*2,radius*2);}}
 const elapsed=now-gatherStart;
 if(letters.length&&gatherStart){const progress=Math.min(1,Math.max(0,(elapsed-250)/1700)),ease=1-Math.pow(1-progress,3);for(const p of letters){const t=Math.max(0,Math.min(1,(ease-p.delay)/(1-p.delay))),turn=Math.sin(t*Math.PI)*.12;const sx=p.sx-w/2,sy=p.sy-h/2;const rotX=sx*Math.cos(turn)-sy*Math.sin(turn)+w/2,rotY=sx*Math.sin(turn)+sy*Math.cos(turn)+h/2;p.x=rotX+(p.tx-rotX)*t;p.y=rotY+(p.ty-rotY)*t;ctx.globalAlpha=(.35+t*.65)*Math.min(1,elapsed/350)*Math.max(0,1-(elapsed-2050)/700);ctx.fillStyle='#d7dce3';ctx.beginPath();ctx.arc(p.x,p.y,p.r*.65,0,Math.PI*2);ctx.fill();if(t<.95){ctx.globalAlpha*=.08;ctx.strokeStyle='#a9badf';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+(p.tx-p.x)*.04,p.y+(p.ty-p.y)*.04);ctx.stroke();}}}
 for(const p of dust){ctx.globalAlpha=Math.max(0,p.life)*.26;ctx.strokeStyle=p.color;ctx.lineWidth=.45;ctx.beginPath();ctx.moveTo(p.px,p.py);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.drawImage(sprite(p.color),p.x-2.5,p.y-2.5,5,5);if(dt){p.px=p.x;p.py=p.y;p.x+=p.vx*dt*.06;p.y+=p.vy*dt*.06;p.life-=p.decay*dt*.06;}}dust=dust.filter(p=>p.life>0);
 if(!paused&&now>nextMeteor){shooters.push({x:w*(.25+Math.random()*.6),y:h*Math.random()*.4,life:1});nextMeteor=now+22000+Math.random()*23000;}for(const p of shooters){ctx.globalAlpha=Math.sin(p.life*Math.PI)*.18;const g=ctx.createLinearGradient(p.x-90,p.y-30,p.x,p.y);g.addColorStop(0,'#adbadf00');g.addColorStop(1,'#d8e3f2');ctx.strokeStyle=g;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-90,p.y-30);ctx.lineTo(p.x,p.y);ctx.stroke();p.x+=dt*.35;p.y+=dt*.115;p.life-=dt*.00065;}shooters=shooters.filter(p=>p.life>0);
 if(flare>0){ctx.globalAlpha=flare*.022;const g=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,Math.max(w,h)*.65);g.addColorStop(0,currentTint);g.addColorStop(1,currentTint+'00');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);flare=Math.max(0,flare-dt*.0004);}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';}
function animate(now){const dt=Math.min(40,previous?now-previous:16);previous=now;paint(now,dt);if(!paused&&!document.hidden)raf=requestAnimationFrame(animate);}
function syncMotion(){cancelAnimationFrame(raf);previous=0;$('motionButton').setAttribute('aria-pressed',String(paused));$('motionButton').textContent=paused?'Resume motion ▷':'Pause motion Ⅱ';if(paused&&scene==='gathering'){letters=[];reveal();}paint(performance.now(),0);if(!paused&&!document.hidden)raf=requestAnimationFrame(animate);}
document.addEventListener('pointermove',move,{passive:true});$('wakeSky').addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY};wake();});$('wakeSky').onclick=()=>wake();
document.addEventListener('keydown',e=>{if(scene==='sleeping'&&(e.key==='Tab'||e.key==='Enter'||e.key===' ')){e.preventDefault();wake(true);input.focus();}});
document.querySelector('.feeling-line').addEventListener('click',e=>{if(e.target!==input){input.focus();openPicker();}});
const observer=new MutationObserver(()=>{if(scene==='sleeping'||scene==='gathering')return;const next=!$('contextStep').hidden?'context':!picker.hidden?'choosing':'prompt';if(next!==scene){setScene(next);if(next==='choosing')burst(w/2,h*.46,'#c5b9ec');}options.querySelectorAll('li').forEach((li,i)=>li.style.setProperty('--i',i));});observer.observe(picker,{attributes:true,attributeFilter:['hidden']});observer.observe($('contextStep'),{attributes:true,attributeFilter:['hidden']});observer.observe(options,{childList:true});
$('motionButton').onclick=()=>{paused=!paused;syncMotion();};reduced.addEventListener('change',e=>{paused=e.matches;syncMotion();});document.addEventListener('visibilitychange',syncMotion);window.addEventListener('resize',size);size();syncMotion();
// Reduced-motion users receive the same functional flow without a forced animation.
if(paused)wake(true);
